"""Render GitHub Pages with the Python standard library: python site/build.py."""
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
DOCS=ROOT/"docs"
REPO="https://github.com/promptowy/naiman"
DOWNLOAD=REPO+"/releases/download/v0.2.0-preview.1/NAIMAN.exe"
XBOX="https://www.xbox.com/remoteplay"

def page(pl):
    def t(en,pol):return pol if pl else en
    lang=t("en","pl");home=t("./","pl.html")
    sony="https://www.playstation.com/"+t("en-us","pl-pl")+"/support/games/playstation-remote-play-on-pc-and-mac/"
    xboxhelp="https://support.xbox.com/"+t("en-US","pl-PL")+"/help/games-apps/game-setup-and-play/how-to-set-up-remote-play"
    def link(url,label):return f'<a href="{url}">{label}</a>'
    def cta():return f'<a class="cta" href="{DOWNLOAD}"><span aria-hidden="true">↓</span>{t("Download for Windows","Pobierz na Windows")}</a>'
    def hardware(key,title):
        return f'<a class="hardware" data-route="{key}" href="#{key}"><span class="choose">{t("Setup guide","Instrukcja konfiguracji")} <span class="arrow" aria-hidden="true">↘</span></span><img src="media/{key}.png" width="450" height="600" alt=""><b>{title}</b></a>'
    def details(n,title,description,trail="",linkpair=None):
        resource=link(*linkpair) if linkpair else ""
        nex=f'<button data-next type="button">{t("Next step","Następny krok")} →</button>' if n<3 else ""
        path=f'<p class="trail">{trail}</p>' if trail else ""
        return f'<details {"open" if n==1 else ""}><summary><span class="num">{n:02}</span>{title}</summary><div class="stepbody"><p>{description}</p>{path}{resource}{nex}</div></details>'
    def route(key):
        xbox=key=="xbox"; device="Xbox" if xbox else "PlayStation 5"
        step1=details(1,t("On the console","Na konsoli"), t("Press the Xbox button on your controller and open Settings. Enable remote features. Leave your Xbox powered on for the first connection.","Naciśnij przycisk Xbox na padzie i otwórz ustawienia. Włącz funkcje zdalne. Na pierwszą próbę zostaw Xboxa włączonego.") if xbox else t("From your PS5 home screen, open Settings, then enable Remote Play. Leave the PS5 on for the first connection.","Na ekranie głównym PS5 otwórz ustawienia i włącz Remote Play. Na pierwsze połączenie zostaw PS5 włączone."),
            t("Settings › Devices & connections › Remote features","Ustawienia › Urządzenia i połączenia › Funkcje zdalne") if xbox else t("Settings › System › Remote Play › Enable Remote Play","Ustawienia › System › Remote Play › Włącz funkcję Remote Play"),
            (xboxhelp if xbox else sony,t("Official Xbox guide","Instrukcja Xbox") if xbox else t("Official PlayStation guide","Instrukcja PlayStation")))
        step2=details(2,t("Connect from your PC","Połącz się z komputera"),t("Click Open Xbox Remote Play in NAIMAN. In Edge, sign in with the Microsoft account from your console, select your Xbox and launch the game. Keep the game tab active.","W NAIMAN kliknij Otwórz Xbox Remote Play. W Edge zaloguj się kontem Microsoft używanym na konsoli, wybierz Xboxa i uruchom grę. Zostaw kartę z grą aktywną.") if xbox else t("Connect your DualSense to the PC by USB. Install and open PS Remote Play from Sony. Sign in with the account used on your console and choose PS5. Wait until you see the game.","Podłącz DualSense do PC przez USB. Pobierz i otwórz PS Remote Play od Sony. Zaloguj się kontem z konsoli, wybierz PS5 i poczekaj, aż zobaczysz grę."),linkpair=(XBOX,t("Open Xbox Remote Play","Otwórz Xbox Remote Play")) if xbox else (sony,t("Get PS Remote Play","Pobierz PS Remote Play")))
        step3=details(3,t("Start smoothing in NAIMAN","Włącz wygładzanie w NAIMAN"),t("Return to NAIMAN. Click I can see the game on PC, confirm the game window and start 2x smoothing. For the Xbox browser player, F11 hides the title bar. Ctrl + Alt + Q exits NAIMAN playback.","Wróć do NAIMAN. Kliknij Widzę grę na komputerze, sprawdź nazwę okna i kliknij Graj z wygładzaniem 2x. W odtwarzaczu Xbox skrót F11 ukrywa pasek przeglądarki. Ctrl + Alt + Q kończy wygładzanie.") if xbox else t("Return to NAIMAN, choose the PS Remote Play window and start 2x smoothing. Ctrl + Alt + B compares the original. This route still awaits testing with a physical PS5.","Wróć do NAIMAN, wybierz okno PS Remote Play i kliknij Graj z wygładzaniem 2x. Ctrl + Alt + B przełącza oryginał. Ta ścieżka czeka jeszcze na test z fizycznym PS5."))
        return f'<article data-path id="{key}" class="path"><h3>{device}</h3>{step1}{step2}{step3}</article>'
    nav=t("Setup","Konfiguracja");results=t("Measurements","Pomiary")
    hero=t('Smoother console play<br><em>on your PC.</em>','Płynniejszy obraz<br><em>z konsoli na PC.</em>')
    copy=t("NAIMAN uses your graphics card to draw a frame between two frames of your game. Choose your console to connect it for the first time.","NAIMAN wykorzystuje kartę graficzną komputera, żeby dorysować klatkę między dwiema klatkami gry. Wybierz swoją konsolę, a przejdziemy przez podłączenie.")
    def faq(title,body):
        return '<details><summary>'+title+'</summary><p>'+body+'</p></details>'
    faqs=faq(t("The Xbox title bar is still visible","Widać pasek Play XBOX"),t("Activate the Xbox window and press F11. In the console routes NAIMAN uses the client area, fits the central 16:9 console picture and opens its borderless output on the same monitor. Other display shapes can retain bars to keep the whole game visible.","Kliknij okno z transmisją i naciśnij F11. W trybie konsoli NAIMAN wybiera obszar obrazu 16:9 i pokazuje go bez ramki na tym samym monitorze. Na monitorach o innych proporcjach mogą zostać pasy, żeby zachować cały kadr."))+faq(t("My window is missing","Nie widzę okna gry na liście"),t("Restore the source window, open the game tab and press Refresh. Choose Find another window if the title differs. If Xbox asks you to resume play, click inside the stream.","Przywróć okno gry, otwórz kartę z transmisją i kliknij Odśwież. Przy innej nazwie skorzystaj z opcji Znajdź inne okno. Jeśli Xbox prosi o wznowienie, kliknij w obraz gry."))+faq(t("I use an HDMI capture card","Mam kartę przechwytującą HDMI"),t("Add the card as a Video Capture Device in OBS. Open the source's Windowed Projector and select it in NAIMAN under Use an HDMI capture card. Enable audio monitoring in OBS if needed. Physical HDMI hardware validation is pending.","Dodaj kartę w OBS jako urządzenie do przechwytywania wideo. Otwórz projektor okienkowy tego źródła. W NAIMAN wybierz Mam kartę przechwytującą i wskaż projektor. Odsłuch ustaw w OBS. Test fizycznej karty jest jeszcze przed nami."))
    html=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta name="description" content="{escape(copy,quote=True)}"><title>NAIMAN | {t("Xbox and PS5 on PC","Xbox i PS5 na PC")}</title><link rel="stylesheet" href="field.css"><script src="guide.js" defer></script></head><body>
<header class="top"><a class="word" href="{home}">NAIMAN</a><nav aria-label="{nav}"><a href="#setup">{nav}</a><a href="#results">{results}</a><a href="{REPO}">GitHub ↗</a></nav><a class="language" lang="{t("pl","en")}" href="{t("pl.html","./")}">{t("PL","EN")}</a></header>
<main><section class="hero"><div class="lead"><h1>{hero}</h1><p>{copy}</p>{cta()}<small class="meta">Windows 11 x64 · SDR · {t("Preview 0.2","Wersja testowa 0.2")}</small></div><div class="choices">{hardware("xbox","Xbox")}{hardware("ps5","PlayStation 5")}</div></section>
<section class="block" id="setup"><div class="sectionhead"><h2>{t("Connect your console","Podłącz konsolę")}</h2><div class="toggles" aria-label="{nav}"><a data-route="xbox" href="#xbox">Xbox</a><a data-route="ps5" href="#ps5">PlayStation 5</a></div></div><div class="guidegrid"><div class="path">{route("xbox")}{route("ps5")}</div><figure class="aside"><img src="naiman-{lang}.png" width="824" height="597" loading="lazy" alt="{t("NAIMAN console picker on Windows","Wybór konsoli w aplikacji NAIMAN na Windows")}"><figcaption class="caption">{t("The first screen you'll see on Windows. Try without a console opens a moving test scene.","Pierwszy ekran po uruchomieniu na Windows. Opcja Test bez konsoli otwiera ruchomą planszę.")}</figcaption></figure></div></section>
<section class="block results" id="results"><div class="sectionhead"><h2>{t("What changes on screen?","Co zmienia się na ekranie?")}</h2></div><div class="stats"><div class="stat"><strong>{t("25.1","25,1")}</strong><small>{t("Original · changes/s","Oryginał · zmiany/s")}</small></div><div class="stat"><strong>{t("46.7","46,7")}</strong><small>NAIMAN 2x · {t("changes/s","zmiany/s")}</small></div></div><p>{t("We replayed the same 30-second GTA VI recording from Xbox Remote Play on an RTX 4090, then counted visible changes during motion. The console's native frame rate and controller latency were not measured.","Ten sam 30-sekundowy klip GTA VI z Xbox Remote Play odtworzyliśmy na RTX 4090. Liczyliśmy widoczne zmiany podczas ruchu. Natywny klatkaż Xboxa i opóźnienie pada pozostają niezmierzone.")}</p>{link("testing.html",t("Read the test method","Zobacz metodę pomiaru")+" →")}</section>
<section class="block support"><div class="sectionhead"><h2>{t("Help with setup","Pomoc przy konfiguracji")}</h2></div>{faqs}</section></main>
<footer class="foot"><a class="word" href="{home}">NAIMAN</a>{link(REPO+"/releases/tag/v0.2.0-preview.1",t("Release and checksum","Wydanie i suma SHA-256"))}{link("credits.html",t("Photo credits","Autorzy zdjęć"))}{link(REPO,"GitHub ↗")}</footer></body></html>'''
    (DOCS/("pl.html" if pl else "index.html")).write_text(html,encoding="utf-8")

for language in (True,False):page(language)
